command:
set -eu; root=$PWD; work=$(mktemp -d "${TMPDIR}/disposable981.XXXXXX"); trap 'rm -rf "$work"' EXIT; mkdir -p "$work/pack" "$work/consumer"; node scripts/package-payload/CheckPackagePayload.ts --pack-destination "$work/pack"; cd "$work/consumer"; npm init -y >/dev/null; npm pkg set type=module; npm install --ignore-scripts --no-audit --no-fund --fetch-retries=0 --fetch-timeout=15000 "$work"/pack/*.tgz >/dev/null; cat > consumer.ts <<'EOF'
import { Runtime } from "@git-stunts/git-warp";
declare const runtime: Runtime;
void runtime.close();
EOF
cat > tsconfig.json <<'EOF'
{"compilerOptions":{"target":"ES2022","module":"NodeNext","moduleResolution":"NodeNext","lib":["ES2022","DOM","DOM.Iterable"],"types":[],"strict":true,"exactOptionalPropertyTypes":true,"noUncheckedIndexedAccess":true,"skipLibCheck":false,"noEmit":true},"files":["consumer.ts"]}
EOF
node "$root/node_modules/typescript/bin/tsc" --version; node "$root/node_modules/typescript/bin/tsc" --project tsconfig.json
